<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import PageHeader from '@/components/ui/PageHeader.vue'
import BaseModal from '@/components/ui/BaseModal.vue'
import StepUpDialog from '@/components/ui/StepUpDialog.vue'
import { request, ApiError, errorMessage } from '@/api/client'
import { assetsApi, type Asset } from '@/api/assetManagement'
import { confirmAction } from '@/composables/useConfirm'
interface Proposal { id: string; assetId: string; kind: string; service: string; summary: string; status: string; revision: string; diff: string; impact: string; risk: string; rollback: string; verification: string; approvedUntil: string; createdAt: string }
interface Execution { id: string; status: string; output: string; backupPath: string; startedAt: string; endedAt: string }
interface Archive { id: string; name: string; version: string; assetId: string; digest: string; createdAt: string; proposalId: string }
const route = useRoute(), proposals = ref<Proposal[]>([]), assets = ref<Asset[]>([]), archives = ref<Archive[]>([])
const selected = ref<Proposal | null>(null), executions = ref<Execution[]>([]), busy = ref(false), error = ref(''), verify = ref(false), editor = ref(false), executionEnabled = ref(false)
const draft = ref({ assetId: '', kind: 'service_restart', service: 'nginx', configPath: '', content: '', summary: '' })
const otp = ref(''), archiveName = ref(''), archiveVersion = ref('')
const path = computed(() => draft.value.service === 'nginx' ? '/etc/nginx/conf.d/aibot-managed.conf' : '/etc/caddy/Caddyfile')
const targets = computed(() => assets.value.filter(a => a.protocol === 'ssh' && a.enabled))
let retry: (() => Promise<void>) | undefined
async function perform(action: () => Promise<void>) { busy.value = true; error.value = ''; try { await action() } catch (e) { if (e instanceof ApiError && e.code === 'step_up_required') { retry = action; verify.value = true } else error.value = errorMessage(e) } finally { busy.value = false } }
function verified() { verify.value = false; const action = retry; retry = undefined; if (action) void perform(action) }
async function load() { await perform(async () => { const [p, a, d, c] = await Promise.all([request<{ items: Proposal[] }>('/changes'), assetsApi.list(), request<{ items: Archive[] }>('/deployment-archives'), request<{ executionEnabled: boolean }>('/changes/capabilities')]); proposals.value = p.items; assets.value = a.items; archives.value = d.items; executionEnabled.value = c.executionEnabled }) }
async function detail(id: string) { await perform(async () => { selected.value = await request<Proposal>(`/changes/${id}`); executions.value = (await request<{ items: Execution[] }>(`/changes/${id}/executions`)).items; otp.value = '' }) }
async function create() { const body = { ...draft.value, configPath: draft.value.kind === 'config_update' ? path.value : '', content: draft.value.kind === 'config_update' ? draft.value.content : '' }; await perform(async () => { const p = await request<Proposal>('/changes', { method: 'POST', body }); editor.value = false; selected.value = p; executions.value = []; proposals.value.unshift(p) }) }
async function approve() { const p = selected.value; if (!p) return; const code = otp.value; otp.value = ''; await perform(async () => { selected.value = await request<Proposal>(`/changes/${p.id}/approve`, { method: 'POST', body: { confirmed: true, revision: p.revision, otp: code } }); await load() }) }
async function execute() { const p = selected.value; if (!p || !await confirmAction({ title: '执行已审批变更', message: `确认在「${assets.value.find(a => a.id === p.assetId)?.name || p.assetId}」执行 ${p.summary}？`, detail: '此操作会变更远端服务。仅允许手工管理的非生产目标；请核对差异和回滚方案。', confirmText: '执行固定操作', danger: true })) return; await perform(async () => { await request(`/changes/${p.id}/execute`, { method: 'POST', body: { confirmed: true, revision: p.revision } }); selected.value = await request<Proposal>(`/changes/${p.id}`); executions.value = (await request<{ items: Execution[] }>(`/changes/${p.id}/executions`)).items; await load() }) }
async function archive() { if (!selected.value) return; const id = selected.value.id; await perform(async () => { await request(`/changes/${id}/archive`, { method: 'POST', body: { name: archiveName.value, version: archiveVersion.value } }); archiveName.value = ''; archiveVersion.value = ''; await load() }) }
onMounted(async () => { await load(); if (typeof route.query.proposal === 'string') await detail(route.query.proposal) })
</script>
<template>
  <PageHeader eyebrow="OPERATE / CHANGES" title="变更与部署档案"><template #actions><button class="btn" :disabled="busy" @click="load">刷新</button><button class="btn btn-primary" :disabled="busy" @click="editor = true">创建提案</button></template></PageHeader>
  <p class="notice notice-warning">仅固定服务与固定配置路径。目标须标记 managed:manual，宝塔托管及生产目标禁止使用此执行器。当前生产部署必须走宝塔 API。</p>
  <p v-if="!executionEnabled" class="notice">SSH 变更执行默认关闭，当前可预览和保存提案。部署档案仅记录成功的固定变更，不代表生产发布。</p>
  <p v-if="error" class="notice notice-danger" role="alert">{{ error }}</p>
  <section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>提案</th><th>目标 / 风险</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in proposals" :key="p.id"><td>{{ p.summary }}<div class="cell-sub">{{ new Date(p.createdAt).toLocaleString() }}</div></td><td>{{ assets.find(a => a.id === p.assetId)?.name || p.assetId }} · {{ p.risk }}</td><td>{{ p.status }}</td><td><button class="btn btn-sm" :disabled="busy" @click="detail(p.id)">审阅 / 记录</button></td></tr><tr v-if="!proposals.length"><td colspan="4">暂无变更提案。</td></tr></tbody></table></div></section>
  <section v-if="selected" class="panel changes-detail"><div class="panel-body stack"><h3>{{ selected.summary }}</h3><p>状态 {{ selected.status }} · 风险 {{ selected.risk }}</p><p>版本 <code>{{ selected.revision }}</code></p><h4>差异</h4><pre class="change-diff">{{ selected.diff }}</pre><h4>影响</h4><p>{{ selected.impact }}</p><h4>回滚方案</h4><p>{{ selected.rollback }}</p><h4>验证步骤</h4><p>{{ selected.verification }}</p><template v-if="selected.status === 'draft'"><label v-if="selected.risk === 'high'">验证器验证码<input v-model="otp" class="input" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="先在设置启用 TOTP" /><span class="form-hint">高风险审批需要新的 6 位验证码，恢复码不可用。</span></label><button class="btn btn-primary" :disabled="busy || (selected.risk === 'high' && otp.length !== 6)" @click="approve">已审阅差异，确认审批</button></template><template v-if="selected.status === 'approved'"><p>审批有效至 {{ new Date(selected.approvedUntil).toLocaleString() }}，仅审批人可执行一次。</p><button class="btn btn-danger" :disabled="busy || !executionEnabled" @click="execute">执行已审批的固定操作</button></template><div v-for="run in executions" :key="run.id"><h4>执行 {{ run.id }} · {{ run.status }}</h4><p>{{ run.startedAt }} → {{ run.endedAt || '进行中' }}</p><p v-if="run.backupPath">远端备份：<code>{{ run.backupPath }}</code></p><pre class="change-diff">{{ run.output || '无输出' }}</pre></div><form v-if="selected.status === 'succeeded'" class="stack" @submit.prevent="archive"><h4>保存部署档案</h4><label>名称<input v-model="archiveName" class="input" required maxlength="200" /></label><label>版本<input v-model="archiveVersion" class="input" required maxlength="100" /></label><div><button class="btn" :disabled="busy">记录此成功版本</button></div></form></div></section>
  <section class="panel changes-detail"><div class="panel-body"><h3>部署档案</h3><p class="form-hint">不可变的成功变更快照与版本摘要，用于追溯；不会自动重新部署。</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>名称 / 版本</th><th>目标</th><th>记录时间</th><th>操作</th></tr></thead><tbody><tr v-for="a in archives" :key="a.id"><td>{{ a.name }} · {{ a.version }}</td><td>{{ assets.find(asset => asset.id === a.assetId)?.name || a.assetId }}</td><td>{{ new Date(a.createdAt).toLocaleString() }}</td><td><button class="btn btn-sm" @click="detail(a.proposalId)">查看原始提案</button></td></tr><tr v-if="!archives.length"><td colspan="4">暂无部署档案。</td></tr></tbody></table></div></section>
  <BaseModal :open="editor && !verify" title="创建固定变更提案" wide @close="!busy && (editor = false)"><form class="stack" @submit.prevent="create"><label>目标资产<select v-model="draft.assetId" class="select" required><option disabled value="">选择手工管理的非生产 SSH 资产</option><option v-for="a in targets" :key="a.id" :value="a.id">{{ a.name }} · {{ a.tags || '未标记管理方式' }}</option></select></label><label>操作<select v-model="draft.kind" class="select"><option value="service_restart">固定服务重启</option><option value="config_update">固定配置更新（高风险）</option></select></label><label>服务<select v-model="draft.service" class="select"><option value="nginx">nginx</option><option value="caddy">caddy</option></select></label><template v-if="draft.kind === 'config_update'"><p>固定路径：<code>{{ path }}</code></p><label>完整新配置<textarea v-model="draft.content" class="input mono" rows="10" maxlength="65536" required spellcheck="false" /></label><p class="notice notice-warning">配置可能包含可执行指令或影响访问控制，审批要求 TOTP。创建提案会只读获取旧配置以生成差异。</p></template><label>摘要<input v-model="draft.summary" class="input" maxlength="500" /></label><p v-if="error" class="notice notice-danger">{{ error }}</p><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="editor = false">取消</button><button class="btn btn-primary" :disabled="busy">生成预览提案</button></div></form></BaseModal>
  <StepUpDialog v-if="verify" title="变更操作前验证身份" @verified="verified" @close="verify = false; retry = undefined" />
</template>
<style scoped>
.changes-detail { margin-top: 20px; }
.change-diff { max-height: 28rem; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; padding: 14px; background: var(--bg-muted, #f1f5f9); border-radius: 8px; }
code { overflow-wrap: anywhere; }
</style>
